result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "stache.py", "content": "#!/usr/bin/env python3
"""stache.py - a small Mustache-subset template renderer.

Supported syntax:
    {{name}}      variable with HTML escaping
    {{{name}}}    raw (unescaped) variable
    {{#key}}...{{/key}}   section: iterates lists, renders dicts/truthy values
                          once, acts as a conditional for booleans
    {{^key}}...{{/key}}   inverted section: renders when key is falsy/missing
    {{! comment}} comment (rendered as nothing)
    {{user.name}} dotted-name lookup

Missing keys render as the empty string.

Usage:
    python stache.py TEMPLATE_FILE DATA_JSON
"""

import json
import re
import sys

_TOKEN_RE = re.compile(r"\{\{\{(.*?)\}\}\}|\{\{(.*?)\}\}", re.DOTALL)


def _escape(value):
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#39;")
    )


class _Node:
    __slots__ = ("kind", "arg", "children")

    def __init__(self, kind, arg="", children=None):
        self.kind = kind          # text | var | raw | section | inverted
        self.arg = arg
        self.children = children


def _parse(template):
    """Parse template into an AST of _Nodes."""
    root = _Node("root", children=[])
    stack = [root]
    pos = 0
    for match in _TOKEN_RE.finditer(template):
        if match.start() > pos:
            stack[-1].children.append(_Node("text", template[pos : match.start()]))
        raw_content = match.group(1)
        if raw_content is not None:
            stack[-1].children.append(_Node("raw", raw_content.strip()))
        else:
            content = match.group(2)
            marker = content[:1]
            name = content[1:].strip()
            if marker == "!":
                pass  # comment: drop
            elif marker == "#":
                node = _Node("section", name, children=[])
                stack[-1].children.append(node)
                stack.append(node)
            elif marker == "^":
                node = _Node("inverted", name, children=[])
                stack[-1].children.append(node)
                stack.append(node)
            elif marker == "/":
                if len(stack) < 2:
                    raise ValueError(f"unmatched closing tag {{{{{content}}}}}")
                opened = stack.pop()
                if opened.arg != name:
                    raise ValueError(
                        f"section mismatch: expected {{{{{opened.arg}}}}}, got {{{{{content}}}}}"
                    )
            else:
                stack[-1].children.append(_Node("var", content.strip()))
        pos = match.end()
    if len(stack) != 1:
        raise ValueError(f"unclosed section {{{{{stack[-1].arg}}}}}")
    if pos < len(template):
        stack[-1].children.append(_Node("text", template[pos:]))
    return root


def _lookup(context_stack, name):
    """Resolve a (possibly dotted) name against the context stack.

    Returns (found, value). Missing keys yield (False, None) so callers can
    render them as empty string.
    """
    parts = name.split(".")
    for frame in reversed(context_stack):
        if not isinstance(frame, dict):
            continue
        value = frame
        found = True
        for part in parts:
            if isinstance(value, dict) and part in value:
                value = value[part]
            else:
                found = False
                break
        if found:
            return True, value
    return False, None


def _truthy(value):
    """Mustache truthiness: False, None, and empties are falsy."""
    if isinstance(value, str):
        return len(value) > 0
    if isinstance(value, (list, dict)):
        return len(value) > 0
    return bool(value)


def _render_nodes(nodes, context_stack):
    out = []
    for node in nodes:
        if node.kind == "text":
            out.append(node.arg)
        elif node.kind == "var":
            found, value = _lookup(context_stack, node.arg)
            if found and value is not None:
                out.append(_escape(value))
        elif node.kind == "raw":
            found, value = _lookup(context_stack, node.arg)
            if found and value is not None:
                out.append(str(value))
        elif node.kind in ("section", "inverted"):
            found, value = _lookup(context_stack, node.arg)
            truthy = found and _truthy(value)
            if node.kind == "inverted" and not truthy:
                out.append("".join(_render_nodes(node.children, context_stack)))
            elif node.kind == "section" and truthy:
                if isinstance(value, list):
                    for item in value:
                        out.append("".join(_render_nodes(node.children, context_stack + [item])))
                else:
                    # dict / scalar truthy value: render once with it as context
                    out.append("".join(_render_nodes(node.children, context_stack + [value])))
    return "".join(out)


def render(template, data):
    """Render *template* (str) with *data* (dict) and return the result."""
    return "".join(_render_nodes(_parse(template).children, [data]))


def main(argv):
    if len(argv) != 3:
        sys.stderr.write(f"usage: {argv[0]} TEMPLATE_FILE DATA_JSON\n")
        return 2
    with open(argv[1], encoding="utf-8") as f:
        template = f.read()
    with open(argv[2], encoding="utf-8") as f:
        data = json.load(f)
    sys.stdout.write(render(template, data))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
"})
